@Mod.EventBusSubscriber(modid="towerofentropy",value=Dist.CLIENT)
public final class A3RuntimeTest {
 static final Path DIR=Path.of(System.getProperty("toe.a3.output","../animation_pipeline/reports/m002_a3"));
 static final String[] ALL={"crouch_idle","crouch_move","jump","fall","swim_idle","swim","hit","knockback","death","bow_idle","bow_shot","bow_move","bow_cancel","consume","drink","torch","chop","backward","left","right","pickaxe","chest","fishing","climb","sword","roll","firstperson","offhand"};
 static boolean sideCamera;
 static final boolean CAMERA_QA=Boolean.getBoolean("toe.c001.qa");
 static final String[] CASES=Boolean.getBoolean("toe.a3_2.vanilla")?new String[]{"pickaxe","bow_shot","consume","swim","jump","offhand","firstperson","chest"}:Boolean.getBoolean("toe.a3.vanillacheck")?new String[]{"pickaxe","chest","fishing","firstperson","offhand"}:Boolean.getBoolean("toe.a3.skincheck")?(CAMERA_QA?new String[]{"sword","roll","bow_shot","bow_cover","consume","torch","crouch_move","jump"}:new String[]{"sword","roll","bow_shot","consume","torch","crouch_move","jump"}):Boolean.getBoolean("toe.a3.finalcheck")?new String[]{"bow_shot","bow_shot","crouch_back","swim"}:Boolean.getBoolean("toe.a3.extra")?new String[]{"bow_shot","bow_move","consume","torch","backward","swim","knockback"}:Boolean.getBoolean("toe.a3.quick")?new String[]{"bow_shot","backward","left","right","consume"}:ALL;
 static final List<Map<String,Object>> CHECKS=new java.util.concurrent.CopyOnWriteArrayList<>(),SERIES=new ArrayList<>();static List<Map<String,Object>> frames;static String scene;static int ticks,title,quit,visit;static boolean opening,done;static long draws;static int initialFood,initialArrows;
 static void check(String n,boolean b,Object d){CHECKS.add(Map.of("test",n,"pass",b,"detail",String.valueOf(d)));com.mojang.logging.LogUtils.getLogger().info("TOE_A3 {} {} {}",n,b,d);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e)throws Exception{if(e.phase!=TickEvent.Phase.END||!Boolean.getBoolean("toe.a3.test")||Boolean.getBoolean("toe.a1_2.iframes"))return;var mc=Minecraft.getInstance();if(done){if(++quit==30)mc.stop();return;}
  if(!opening&&mc.screen instanceof TitleScreen&&mc.getOverlay()==null&&++title>60){opening=true;mc.options.pauseOnLostFocus=false;mc.createWorldOpenFlows().loadLevel(mc.screen,System.getProperty("toe.a3.world","TOE_A3"));}
  if(mc.player==null||mc.level==null||mc.getOverlay()!=null)return;
  if(Boolean.getBoolean("toe.global.coverage")&&(mc.screen instanceof net.minecraft.client.gui.screens.PauseScreen||mc.screen instanceof net.minecraft.client.gui.screens.OptionsScreen))mc.setScreen(null);
  ++ticks;
  if(Boolean.getBoolean("toe.global.coverage")){if("pickaxe".equals(scene)||"chop".equals(scene))mc.mouseHandler.grabMouse();else mc.mouseHandler.releaseMouse();if(scene!=null){mc.player.setYRot(0);mc.player.setXRot(scene.equals("chest")?30:0);}}
  if(ticks==5){A12RuntimeTest.preview(mc);mc.setScreen(null);mc.options.hideGui=true;mc.options.setCameraType(CAMERA_QA?CameraType.THIRD_PERSON_BACK:CameraType.THIRD_PERSON_FRONT);mc.options.fov().set(50);}
  if(Boolean.getBoolean("toe.a3.circuit")){if(ticks==80)server(p->{try{circuit(p);}catch(Exception ex){check("circuit",false,ex);}});if(ticks==110){release(mc);mc.options.hideGui=false;mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);save();done=true;}return;}
  if(visit>0||Boolean.getBoolean("toe.a3.restart")){if(ticks==70){check("startup_auto",ClientCombatState.mode==CombatController.Mode.AUTO&&PlayerRendererR3.enabled&&PlayerRendererR3.drawCalls>0,"AUTO R3 without commands");check("startup_clear",!ClientRollMotion.busy()&&ClientCombatState.clip().isEmpty(),"no stuck combat");save();done=true;}return;}
  if(ticks<90)return;int elapsed=ticks-90,index=elapsed/100,phase=elapsed%100;
  if(index>=CASES.length){release(mc);if(phase==0)server(p->{try{circuit(p);}catch(Exception ex){check("circuit",false,ex);}});if(phase==15){mc.level.disconnect();mc.clearLevel(new TitleScreen());opening=false;title=0;ticks=0;visit=1;}return;}
  scene=CASES[index];
  if(Boolean.getBoolean("toe.a3.vanillacheck")&&scene.equals("pickaxe")&&phase==18)check("mining_target_ray",mc.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit&&hit.getBlockPos().equals(new BlockPos(0,101,2)),"hit="+mc.hitResult+" yaw="+mc.player.getYRot()+" pitch="+mc.player.getXRot()+" pos="+mc.player.position());
  if(phase==0){sideCamera=Boolean.getBoolean("toe.a3.extra")&&(!Boolean.getBoolean("toe.a3.finalcheck")||index>0);release(mc);mc.options.setCameraType(scene.equals("firstperson")?CameraType.FIRST_PERSON:CAMERA_QA?CameraType.THIRD_PERSON_BACK:CameraType.THIRD_PERSON_FRONT);frames=new ArrayList<>();SERIES.add(Map.of("name",scene,"angle",sideCamera?"side":CAMERA_QA?"shoulder":"front","frames",frames));Files.createDirectories(DIR.resolve("screenshots/"+(sideCamera?"side/":"")+scene));draws=PlayerRendererR3.drawCalls;String s=scene;server(p->{try{fixture(p,s);}catch(Exception ex){check("fixture_"+s,false,ex);}});}
  boolean moving=phase>=20&&phase<72&&Set.of("crouch_move","crouch_back","swim","bow_move","backward","left","right").contains(scene);
  mc.options.keyUp.setDown(moving&&!Set.of("backward","crouch_back","left","right").contains(scene));mc.options.keyDown.setDown(moving&&(scene.equals("backward")||scene.equals("crouch_back")));mc.options.keyLeft.setDown(moving&&scene.equals("left"));mc.options.keyRight.setDown(moving&&scene.equals("right"));mc.options.keyShift.setDown(phase>=15&&phase<80&&scene.startsWith("crouch"));mc.options.keyJump.setDown(scene.equals("jump")&&phase>=25&&phase<28);mc.options.keySprint.setDown(scene.equals("swim")&&moving);
  if(Set.of("bow_shot","bow_cover","bow_move","bow_cancel","consume","drink","fishing","chest").contains(scene)){if(phase==20)KeyMapping.click(mc.options.keyUse.getKey());mc.options.keyUse.setDown(phase>=20&&phase<(scene.equals("bow_cancel")?35:60));}
  if(scene.equals("bow_cancel")&&phase==35)server(p->p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_SWORD)));
  if(scene.equals("chop")||scene.equals("pickaxe")){if(phase==20)KeyMapping.click(mc.options.keyAttack.getKey());mc.options.keyAttack.setDown(phase>=20&&phase<65);}
  if((scene.equals("sword")||scene.equals("firstperson")||scene.equals("offhand"))&&phase==25)KeyMapping.click(mc.options.keyAttack.getKey());
  if(scene.equals("roll")&&phase==25)KeyMapping.click(ActionKeys.ROLL.getKey());
  if((scene.equals("hit")||scene.equals("knockback"))&&phase==25)server(p->{float before=p.getHealth();boolean applied=p.hurt(p.damageSources().generic(),2);check(scene+"_real_damage",applied&&p.getHealth()<before,"before="+before+" after="+p.getHealth());if(scene.equals("knockback"))p.knockback(.4,0,1);});
  if(scene.equals("death")&&phase==25)server(p->p.hurt(p.damageSources().genericKill(),1000));
  if(scene.equals("death")&&phase==65&&mc.player.isDeadOrDying()){mc.player.respawn();mc.setScreen(null);}
  if(scene.equals("chest")&&phase==65){check("chest_interface",mc.screen instanceof net.minecraft.client.gui.screens.inventory.AbstractContainerScreen,"vanilla container opened without animation delay");mc.player.closeContainer();mc.setScreen(null);}
  if(phase>=16&&phase<=86&&phase%2==0){String file=(sideCamera?"side/":"")+scene+"/"+String.format(java.util.Locale.ROOT,"%03d.png",phase);Screenshot.grab(DIR.toFile(),file,mc.getMainRenderTarget(),m->{});var row=new LinkedHashMap<String,Object>();var c=PlayerRendererR3.controller();row.put("src","screenshots/"+file);row.put("t",phase/20.0);row.put("clip",c==null?"none":c.getAnimationName());row.put("time",c==null?0:c.getAnimationTime());row.put("selected",String.valueOf(VisualContext.selected()));row.put("draws",PlayerRendererR3.drawCalls);row.put("health",mc.player.getHealth());row.put("using",mc.player.isUsingItem());row.put("useTicks",mc.player.getTicksUsingItem());row.put("ground",mc.player.onGround());row.put("water",mc.player.isInWater());row.put("crouch",mc.player.isCrouching());row.put("item",mc.player.getMainHandItem().getItem().toString());row.put("visual",A12Probe.sample());frames.add(row);}
  if(phase==92){check(scene+"_renderer",PlayerRendererR3.errors==0,"errors="+PlayerRendererR3.errors+" draws="+(PlayerRendererR3.drawCalls-draws));String s=scene;server(p->{if(s.startsWith("bow_")&&!s.equals("bow_idle")){int arrows=p.getInventory().countItem(Items.ARROW);check(s+"_vanilla_arrows",s.equals("bow_cancel")?arrows==64:arrows==63,"arrows="+arrows);if(!s.equals("bow_cancel")){
    var projectiles=p.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.projectile.AbstractArrow.class,p.getBoundingBox().inflate(64));
    check(s+"_projectile",!projectiles.isEmpty(),"real vanilla arrow");
    if(CAMERA_QA&&s.equals("bow_shot"))
     check("bow_shot_direction",projectiles.stream().anyMatch(a->a.getOwner()==p&&a.getZ()>8.5&&a.getZ()<9.2&&Math.abs(a.getX()-.5)<.55),
      projectiles.stream().map(a->a.position().toString()).toList());
    if(CAMERA_QA&&s.equals("bow_cover"))
     check("bow_cover_stops_arrow",projectiles.stream().anyMatch(a->a.getOwner()==p&&a.getZ()>4.8&&a.getZ()<5.1),
      projectiles.stream().map(a->a.position().toString()).toList());
   }}
   if(s.equals("consume"))check("vanilla_food",p.getFoodData().getFoodLevel()>8&&p.getMainHandItem().getCount()==63,"food="+p.getFoodData().getFoodLevel()+" stack="+p.getMainHandItem());if(s.equals("drink"))check("vanilla_drink",p.getMainHandItem().is(Items.GLASS_BOTTLE),p.getMainHandItem());if(s.equals("death"))check("respawn_restored",p.isAlive()&&p.getHealth()>0,"alive="+p.isAlive());if(s.equals("pickaxe"))check("vanilla_mining",p.serverLevel().getBlockState(new BlockPos(0,101,2)).isAir(),"target block broken");});}
 }
 static void fixture(ServerPlayer p,String s)throws Exception{A12RuntimeTest.fixture(p,Set.of("sword","roll","firstperson","offhand").contains(s));var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getFoodData().setFoodLevel(20);p.invulnerableTime=0;l.getGameRules().getRule(net.minecraft.world.level.GameRules.RULE_KEEPINVENTORY).set(true,p.server);
  p.getInventory().clearContent();if(Set.of("sword","roll","firstperson","offhand").contains(s))p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.IRON_SWORD));
  if(s.startsWith("bow")){p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.BOW));p.getInventory().setItem(9,new ItemStack(Items.ARROW,64));for(int x=-2;x<=2;x++)for(int y=100;y<=104;y++)l.setBlockAndUpdate(new BlockPos(x,y,9),Blocks.HAY_BLOCK.defaultBlockState());}
  if(s.equals("bow_cover"))for(int y=100;y<=103;y++)l.setBlockAndUpdate(new BlockPos(0,y,5),Blocks.STONE.defaultBlockState());
  if(s.equals("consume")){p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.APPLE,64));p.getFoodData().setFoodLevel(8);}
  if(s.equals("drink")){var item=net.minecraft.world.item.alchemy.PotionUtils.setPotion(new ItemStack(Items.POTION),net.minecraft.world.item.alchemy.Potions.WATER);p.setItemSlot(EquipmentSlot.MAINHAND,item);}
  if(s.equals("torch"))p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.TORCH,64));
  if(s.equals("fishing"))p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.FISHING_ROD));
  if(s.equals("chop")||s.equals("pickaxe")){p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(s.equals("chop")?Items.IRON_AXE:Items.IRON_PICKAXE));l.setBlockAndUpdate(new BlockPos(0,101,2),(s.equals("chop")?Blocks.OAK_LOG:Blocks.STONE).defaultBlockState());}
  if(s.equals("chest")){l.setBlockAndUpdate(new BlockPos(0,100,2),Blocks.CHEST.defaultBlockState());p.teleportTo(l,.5,100,.5,0,30);}
  if(s.startsWith("swim")){for(int x=-3;x<=3;x++)for(int z=-3;z<=12;z++)for(int y=95;y<=102;y++)l.setBlockAndUpdate(new BlockPos(x,y,z),(y==95?Blocks.STONE:Blocks.WATER).defaultBlockState());p.teleportTo(l,.5,99,.5,0,0);}
  if(s.equals("fall"))p.teleportTo(l,.5,106,.5,0,0);
  if(s.equals("climb")){for(int y=100;y<=106;y++){l.setBlockAndUpdate(new BlockPos(0,y,1),Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(new BlockPos(0,y,0),Blocks.LADDER.defaultBlockState());}p.teleportTo(l,.5,100,.5,0,0);}
  if(s.equals("offhand"))p.setItemSlot(EquipmentSlot.OFFHAND,new ItemStack(Items.SHIELD));
  if(p.getMainHandItem().getItem() instanceof SwordItem)WeaponReadiness.toggle(p);
 }
 static void circuit(ServerPlayer p)throws Exception{A12RuntimeTest.fixture(p,true);var l=p.serverLevel();for(int x=-24;x<=24;x++)for(int z=-24;z<=24;z++)l.setBlockAndUpdate(new BlockPos(x,99,z),Blocks.STONE.defaultBlockState());for(int x=8;x<=18;x++)for(int z=3;z<=15;z++)for(int y=95;y<=99;y++)l.setBlockAndUpdate(new BlockPos(x,y,z),(y==95?Blocks.STONE:Blocks.WATER).defaultBlockState());for(int z=4;z<=12;z++){l.setBlockAndUpdate(new BlockPos(-8,100,z),Blocks.OAK_LOG.defaultBlockState());l.setBlockAndUpdate(new BlockPos(-10,100,z),Blocks.STONE.defaultBlockState());}for(int x=-3;x<=3;x++)for(int y=100;y<=104;y++)l.setBlockAndUpdate(new BlockPos(x,y,18),Blocks.HAY_BLOCK.defaultBlockState());for(int x=-18;x<=-14;x++)for(int z=-3;z<=3;z++)l.setBlockAndUpdate(new BlockPos(x,103,z),Blocks.STONE.defaultBlockState());
  p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getFoodData().setFoodLevel(20);p.setHealth(20);p.getInventory().clearContent();Item[] items={Items.IRON_SWORD,Items.BOW,Items.IRON_PICKAXE,Items.IRON_AXE,Items.APPLE,Items.TORCH,Items.WATER_BUCKET,Items.OAK_PLANKS,Items.POTION};for(int i=0;i<items.length;i++)p.getInventory().setItem(i,new ItemStack(items[i],i==4||i==5||i==7?64:1));p.getInventory().setItem(9,new ItemStack(Items.ARROW,64));p.getInventory().selected=0;p.setRespawnPosition(l.dimension(),new BlockPos(0,100,0),0,true,false);finishCircuit(p);check("playable_circuit",true,"TOE_A3: pool east, mining west, archery north, ledge west; inventory supplied");}
 static void server(java.util.function.Consumer<ServerPlayer> work){var mc=Minecraft.getInstance();var id=mc.player.getUUID();mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(id);if(p!=null)work.accept(p);});}
 static void finishCircuit(ServerPlayer p){var l=p.serverLevel();p.server.setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);
  for(int z=-10;z<=-4;z++)for(int x=-1;x<=1;x++)l.setBlockAndUpdate(new BlockPos(x,101,z),Blocks.STONE_SLAB.defaultBlockState().setValue(net.minecraft.world.level.block.SlabBlock.TYPE,net.minecraft.world.level.block.state.properties.SlabType.TOP));
  for(int step=0;step<3;step++)for(int z=-2;z<=2;z++)for(int y=100;y<=100+step;y++)l.setBlockAndUpdate(new BlockPos(-11-step,y,z),Blocks.STONE.defaultBlockState());
  for(int x=-20;x<=-14;x++)for(int z=10;z<=16;z++)if(x==-20||x==-14||z==10||z==16)l.setBlockAndUpdate(new BlockPos(x,100,z),Blocks.OAK_FENCE.defaultBlockState());
  l.setBlockAndUpdate(new BlockPos(-17,100,10),Blocks.OAK_FENCE_GATE.defaultBlockState());var zombie=new net.minecraft.world.entity.monster.Zombie(net.minecraft.world.entity.EntityType.ZOMBIE,l);zombie.setPos(-17.5,100,13.5);zombie.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));zombie.setPersistenceRequired();l.addFreshEntity(zombie);
  l.setBlockAndUpdate(new BlockPos(-3,100,0),Blocks.CHEST.defaultBlockState());if(l.getBlockEntity(new BlockPos(-3,100,0)) instanceof net.minecraft.world.level.block.entity.ChestBlockEntity chest){chest.setItem(0,new ItemStack(Items.APPLE,64));chest.setItem(1,new ItemStack(Items.ARROW,64));chest.setItem(2,net.minecraft.world.item.alchemy.PotionUtils.setPotion(new ItemStack(Items.POTION),net.minecraft.world.item.alchemy.Potions.WATER));}
 }
 @SubscribeEvent public static void camera(net.minecraftforge.client.event.ViewportEvent.ComputeCameraAngles e)throws Exception{if(!sideCamera||Minecraft.getInstance().player==null)return;var center=Minecraft.getInstance().player.getEyePosition((float)e.getPartialTick());var d=e.getCamera().getPosition().subtract(center);var m=Camera.class.getDeclaredMethod("setPosition",double.class,double.class,double.class);m.setAccessible(true);m.invoke(e.getCamera(),center.x-d.z,center.y+d.y,center.z+d.x);e.setYaw(e.getYaw()+90);}
 static void release(Minecraft mc){for(var k:new KeyMapping[]{mc.options.keyUp,mc.options.keyDown,mc.options.keyLeft,mc.options.keyRight,mc.options.keyShift,mc.options.keyJump,mc.options.keySprint,mc.options.keyAttack,mc.options.keyUse})k.setDown(false);}
 static void save()throws Exception{Files.createDirectories(DIR);Files.writeString(DIR.resolve(Boolean.getBoolean("toe.a3.circuit")?"CIRCUIT.json":Boolean.getBoolean("toe.a3.restart")?"RESTART.json":Boolean.getBoolean("toe.a3.finalcheck")?"FINAL_CHECKS.json":Boolean.getBoolean("toe.a3.extra")?"EXTRA.json":Boolean.getBoolean("toe.a3.quick")?"QUICK.json":"RUNTIME.json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("checks",CHECKS,"series",SERIES,"renderErrors",PlayerRendererR3.errors)));}
}
